SourceCode.Declaration:
/// <summary>
/// Extension of SalesAgreementHeader
/// </summary>
[ExtensionOf(tableStr(SalesAgreementHeader))]
final public class AVASalesAgreementHeaderDbt_Extension
{
}

Method.Source:
public void insert()
{
    next insert();

    this.avaCreateMarkupTrans(false);
}

public void update()
{
    SalesAgreementHeader    avaAgreementHeaderOrig = this.orig();
    AgreementHeaderDefault  avaHeaderDefaultOrig = this.agreementHeaderDefault().orig();
    next update();

    if (this.CustAccount != avaAgreementHeaderOrig.CustAccount ||
        this.agreementHeaderDefault().MiscChargeGroup  != avaHeaderDefaultOrig.MiscChargeGroup)
    {
        this.avaCreateMarkupTrans();
    }
}

/// <summary>
/// Create <c>MarkupTrans</c> records
/// </summary>
/// <param name = "_deleteExistingMarkupTrans">boolean</param>
void  avaCreateMarkupTrans(
    boolean _deleteExistingMarkupTrans = true
)
{
    AgreementHeaderDefault avaHeaderDefault = this.agreementHeaderDefault();

    if (avaHeaderDefault.AVASkipCreateMarkup == NoYes::No)
    {

        Markup::insertMarkupTrans(HeadingLine::Heading,
                                MarkupModuleType::Cust,
                                this,
                                this.CustAccount,
                                avaHeaderDefault.MiscChargeGroup,
                                this.Currency,
                                this.Language,
                                '',
                                avaHeaderDefault.MiscChargeGroup,
                                false,
                                _deleteExistingMarkupTrans,
                                avaHeaderDefault.DeliveryMode,
                                DlvMode::find(avaHeaderDefault.DeliveryMode).MarkupGroup);
    }
}
